export const code = async (inputs) => {
  const pkgs = Array.isArray(inputs.packages) ? inputs.packages : [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const stages = ['d_minus_6', 'd_minus_1', 'd_plus_1', 'd_plus_7', 'd_plus_14', 'd_plus_21', 'd_plus_28'];
  const thresholds = { d_minus_6: 39, d_minus_1: 44, d_plus_1: 46, d_plus_7: 52, d_plus_14: 59, d_plus_21: 66, d_plus_28: 73 };
  const messages = {
    d_minus_6: "Friendly reminder: Your child's tennis package expires in 6 days. Please renew to continue training at Arnav Jain Tennis Academy.",
    d_minus_1: "Urgent: Your child's tennis package expires tomorrow! Renew now to avoid disruption at Arnav Jain Tennis Academy.",
    d_plus_1: "Your child's tennis package has expired. Renew today to resume training at Arnav Jain Tennis Academy.",
    d_plus_7: "It has been a week since your package expired. We miss your child! Renew now for special rates at Arnav Jain Tennis Academy.",
    d_plus_14: "Your child has been away for 2 weeks. Come back with our renewal offer at Arnav Jain Tennis Academy!",
    d_plus_21: "Three weeks since expiry. Your child's spot is waiting. Renew today at Arnav Jain Tennis Academy!",
    d_plus_28: "Last reminder: Your package expired a month ago. Final renewal notice from Arnav Jain Tennis Academy."
  };
  let stage = 'fallback';
  let pkgId = '';
  let studentId = '';
  let message = '';
  for (const s of stages) {
    const candidates = pkgs.filter(p => {
      const start = new Date(p.start_date);
      start.setHours(0, 0, 0, 0);
      const diffMs = today.getTime() - start.getTime();
      const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
      return diffDays >= thresholds[s] && p.reminder_stage !== s && p.status !== 'expired';
    });
    if (candidates.length > 0) {
      stage = s;
      pkgId = String(candidates[0].id || '');
      studentId = String(candidates[0].student_id || '');
      message = messages[s] || '';
      break;
    }
  }
  const isFallback = stage === 'fallback';
  return {
    stage: stage,
    is_fallback: isFallback ? 'true' : 'false',
    package_id: pkgId,
    student_id: studentId,
    message: message
  };
};
